export type Language = keyof typeof translations;
export type TranslationKey = keyof typeof translations.en;
export type Dictionary = Record<TranslationKey, string>;

export function dictionaryHasParity(): boolean {
  return Object.keys(translations.en).length === Object.keys(translations.my).length && Object.keys(translations.en).every((key) => key in translations.my);
}
